import{_ as a,o as s,c as o,a5 as i}from"./chunks/framework.BwlBv862.js";const u=JSON.parse('{"title":"Arquitetura e limites da demonstração no navegador","description":"","frontmatter":{"title":"Arquitetura e limites da demonstração no navegador","docId":"developer.demo","translationKey":"developer.demo","locale":"pt","audience":"developer","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"9aec97bb1d4bc623c4f9b64478668231fad203638ef4b6eb62369d8e7eebd6ec","translationRevision":"33456a9bc5d6c41b26f7c34952478e24f26632a271664c9a665db1c24bd43a86","order":140},"headers":[],"relativePath":"pt/developer/demo.md","filePath":"pt/developer/demo.md","lastUpdated":1794615808000}'),t={name:"pt/developer/demo.md"};function n(r,e,d,p,c,l){return s(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="browser-demo-architecture-and-limits" tabindex="-1">Arquitetura e limites da demonstração no navegador <a class="header-anchor" href="#browser-demo-architecture-and-limits" aria-label="Permalink to &quot;Arquitetura e limites da demonstração no navegador {#browser-demo-architecture-and-limits}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo e pré-requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Explore a interface real do aplicativo com dados sintéticos em um navegador. Use Bun 1.4.4 e a instalação travada do repositório. A entrada explícita da demonstração funciona independentemente de Rust, contas e de um host em execução. Seu runtime e suas verificações de aceitação no navegador fazem parte deste repositório.</p><h2 id="build-and-inspect" tabindex="-1">Compile e inspecione <a class="header-anchor" href="#build-and-inspect" aria-label="Permalink to &quot;Compile e inspecione {#build-and-inspect}&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> site</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> site</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preview</span></span></code></pre></div><p>Para uma prévia local sem commit, use <code>TIKTOOLS_SITE_ALLOW_DIRTY=1 bun scripts/task.ts site build</code>. Seu manifesto fica marcado como sujo e a publicação o rejeita. A montagem final exige que os dois bundles informem o mesmo SHA Git limpo e a mesma base; recompile após o commit. Execute um servidor de desenvolvimento ou prévia somente quando o trabalho local de navegador for desejado. <code>docs</code> é responsável pelo VitePress e <code>demo</code> pelo bundle do aplicativo de navegador; <code>site build</code> os monta em um site estático. O workspace de documentação mantém sua dependência VitePress separada das ferramentas Vite 8 do aplicativo. Comandos não devem instalar dependências silenciosamente nem invocar Cargo.</p><h2 id="preserve-the-application-boundary" tabindex="-1">Preserve o limite do aplicativo <a class="header-anchor" href="#preserve-the-application-boundary" aria-label="Permalink to &quot;Preserve o limite do aplicativo {#preserve-the-application-boundary}&quot;">​</a></h2><p><code>src/web/app/mount-workspace.ts</code> fornece a fábrica compartilhada de app/Pinia/roteador; importá-la não monta nem escolhe um transporte. A inicialização explícita da demonstração fornece <code>src/web/demo/runtime/transport.ts</code> no limite compartilhado de <code>ControlTransport</code>/cliente de controle. Dados iniciais puros ficam em <code>demo/fixtures/base-host.ts</code>, independentemente do Playwright. <code>shared/lib/app-storage.ts</code> e <code>demo/storage.ts</code> fornecem adaptadores de armazenamento isolados para que redefinições não limpem preferências nativas nem outra instância da demonstração. Páginas, widgets e recursos devem usar seus stores de entidades e chamadas de <code>src/web/shared/api</code> existentes. Não crie um segundo aplicativo de imitação, injete APIs nativas falsas na inicialização nativa comum nem deixe requisições da demonstração chegarem a um host real.</p><p><code>demo/scenarios.ts</code> valida 11 IDs de cenário e as rotas/idiomas/tutoriais permitidos. <code>runtime/host.ts</code> registra manipuladores explícitos de métodos; a descoberta lista esses manipuladores, IDs de requisição são repetidos em <code>rpc-response</code> e efeitos incompatíveis retornam erro imediatamente. O host inicializa registros fictícios e avança um relógio fixo um passo por Next event. Play e Next event primeiro conectam o criador fictício pelo RPC simulado quando necessário e depois entregam um evento imediato. Play continua a cada dois segundos; Pause para a produção. A barra de ferramentas exibe o estado da reprodução e a contagem de eventos. O fluxo para em 300 passos e mantém no máximo 60 eventos de feed e 60 execuções. Filas de resposta e registros armazenados têm limites separados.</p><p>O parâmetro de consulta <code>embed=connection|feed|automation|points|overlays</code> seleciona um exemplo focado para incorporação. Ele omite a navegação geral e a barra completa da demonstração, mantendo os componentes, as páginas e o runtime reais. Use a rota correspondente ao painel escolhido e não combine esse modo com um tutorial. A demonstração completa continua disponível pelo link de abertura, que remove o parâmetro de incorporação.</p><p>Reset limpa apenas o prefixo atual <code>tiktools.demo.&lt;instance&gt;.*</code> e recarrega o quadro. Recarregar redefine singletons de módulos, diários, i18n e diagnósticos. Quadros incorporados diferentes recebem IDs distintos de instância. Sair da página desmonta Vue, descarta stores, desconecta cliente/transporte e limpa os dois temporizadores. A demonstração não instala uma ponte <code>window.ipc</code> nem realiza HTTP arbitrário, shell, RCON, execução de scripts de visitantes ou instalação nativa de atualizações. Sua CSP rejeita conexões de rede. Modelos de registro e simulação de filtros usam funções compartilhadas puras; são exemplos do contrato de frontend, não substitutos da execução Rust.</p><p>A entrada compartilhada <code>startTour(id, {router, capabilities, taskState})</code> e o <code>tourRegistry</code> exportado ficam em <code>src/web/features/guided-help/index.ts</code>. Sete tutoriais versionados usam alvos estáveis de página e catálogos separados para cada idioma compatível. Eles carregam Driver.js apenas sob solicitação, restringem alvos ao workspace, respeitam movimento reduzido, restauram o foco e cancelam esperas limitadas na navegação. Dispensar nunca conclui uma tarefa nem executa uma ação do aplicativo. A seleção de tutorial nomeia a tarefa completa, prepara o cenário correspondente e pausa a reprodução antes de iniciar. O controle de fechar do Driver dispensa o guia; a barra de ferramentas informa o resultado. Reset limpa o progresso versionado desta instância.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado e status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado e status {#expected-result-and-status}&quot;">​</a></h2><p>A demonstração apresenta navegação, edição local, apresentação de eventos e estados de recuperação compatíveis com seu modelo de cenários. Ela não valida sessões reais do TikTok, fonte de navegador do OBS, comportamento Wry/nativo, backend de produção nem vários PCs. Rankings permanece oculto; Changes de Automations é apenas local, Variables revisadas são trabalho nativo real do produto, Changes de Overlays continua como uma continuação não mesclada e os controles de instalação automática do atualizador são experimentais.</p><h2 id="components-and-markdown" tabindex="-1">Componentes e Markdown <a class="header-anchor" href="#components-and-markdown" aria-label="Permalink to &quot;Componentes e Markdown {#components-and-markdown}&quot;">​</a></h2><p><code>docs/examples/*.vue</code> fornece tanto o catálogo renderizado quanto os trechos de código-fonte. Botões pequenos renderizam diretamente no Markdown sem estilos globais de desktop. Diálogos com estado, exemplos de layout e páginas do aplicativo usam <code>DemoFrame</code>, que constrói URLs validadas e compatíveis com a base. Nas páginas de artigos, o comportamento padrão carrega o iframe apenas sob solicitação. A opção pública <code>VITE_TIKTOOLS_PUBLIC_UI_KIT=1</code> expõe o catálogo de componentes sem habilitar todas as ferramentas de desenvolvimento do desktop.</p><p>Para colocar um painel de conexão junto às instruções de uma página em português, use:</p><div class="language-vue vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">DemoFrame</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> scenario</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;connection&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> locale</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pt&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> panel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;connection&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Pratique sua primeira conexão&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div><p>A propriedade <code>panel</code> aceita <code>connection</code>, <code>feed</code>, <code>automation</code>, <code>points</code> ou <code>overlays</code>. Por padrão, um convite neutro para iniciar o exemplo aparece antes da interação; ele não imita a interface do aplicativo. O iframe só é carregado quando o leitor escolhe experimentar.</p><p>Na página inicial, <code>DemoFrame</code> usa as propriedades booleanas <code>autoload</code> e <code>minimal</code> para carregar diretamente a interface real em uma apresentação compacta. O leitor escolhe entre cinco abas de tarefas: conexão, atividade ao vivo, automações, pontos e sobreposições. Apenas o iframe da aba selecionada permanece ativo; a página não usa <code>ScenePreview</code> nem uma imitação visual do produto. Para criar uma incorporação com o mesmo comportamento, use:</p><div class="language-vue vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">DemoFrame</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> scenario</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;connection&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> locale</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pt&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> panel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;connection&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Experimente o TikTools&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> autoload</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> minimal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div><p>Reserve a altura do quadro antes de o aplicativo terminar de carregar para evitar deslocamentos de conteúdo. Cada exemplo mantém sua instância de armazenamento isolada, e o controle de reinício limpa somente essa instância. O link para abrir a demonstração completa sai do modo incorporado e permite explorar o workspace. Mantenha as instruções e o resultado esperado próximos ao exemplo, usando <code>DocSteps</code> para sequências e <code>DocCallout</code> para orientações contextuais.</p><h2 id="recovery-and-verification" tabindex="-1">Recuperação e verificação <a class="header-anchor" href="#recovery-and-verification" aria-label="Permalink to &quot;Recuperação e verificação {#recovery-and-verification}&quot;">​</a></h2><p>Redefina um cenário após uma lacuna ou falha simulada intencionalmente. Se ele contatar um serviço externo, pare e corrija o limite do transporte. Verifique conteúdo, compilação da demonstração e montagem do site independentemente; uma compilação de documentação não comprova correção nativa. <a href="./testing.html">Testes</a> distingue evidências de host simulado, navegador, Rust e aceitação manual.</p>`,24)])])}const h=a(t,[["render",n]]);export{u as __pageData,h as default};
